            m_gapDryRun.paused = false; m_gapDryRun.active = false; m_gapDryRun.result = 1U; s.curveTerminalHold = false;
            m_gapDryRun.epoch = m_motion.GetCurrentExecutionEpoch(); m_gapDryRun.lease = m_programMotionLease;
